const u = $json, m = u.message || {}, cb = u.callback_query || {}, rt = m.reply_to_message || {};
const SUP = '-1003886197648', REL = '-1003553184281';
const chat = String(m.chat ? m.chat.id : (cb.message && cb.message.chat ? cb.message.chat.id : ''));
const numDe = t => { const p = String(t || '').split('CH-'); return p.length > 1 ? 'CH-' + p[1].split('\n')[0].trim() : ''; };
let rota = 'nada';
if (m.text && rt.from && rt.from.is_bot && (chat === SUP || chat === REL) && (String(rt.text || '').includes('CHAMADO NOVO') || String(rt.text || '').includes('PRÉVIA - chamado CH-'))) rota = 'reply';
else if (String(cb.data || '').includes('enviar_') && cb.message && (chat === SUP || chat === REL)) rota = 'enviar';
else if ((String(cb.data || '').includes('afpago_') && chat === REL) || (chat === REL && String(rt.text || '').includes('COMISSÃO DE AFILIADO') && String(m.text || '').trim().toLowerCase().replace(/[^a-z]/g, '') === 'ok')) rota = 'afiliado';
const o = { rota, chat };
if (rota === 'reply') Object.assign(o, { numero: numDe(rt.text), texto: String(m.text).trim(), msg_id: String(m.message_id) });
if (rota === 'enviar') {
  const t = String(cb.message.text || '');
  const texto = t.replace(/^[\s\S]*?\n\n/, '').replace(/\n\n---\nToque em Enviar[\s\S]*$/, '').trim();
  const id = String(cb.data).replace('enviar_', '');
  Object.assign(o, { numero: numDe(t), texto, previa: 'previa_' + id + chat, enviada: 'enviada_' + id + chat, cb_id: String(cb.id), msg_id: String(cb.message.message_id) });
}
return [{ json: o }];

const c = $('Classificar').first().json;
const r = $('Reply: ler chamados').all().map(i => i.json).filter(x => x && x.row_number && String(x.chamado_id).trim() === c.numero).pop();
let caso = 'comum';
if (!r) caso = 'nao_achou'; else if (!String(r.email || '').includes('@')) caso = 'sem_email'; else if (String(r.problema || '').includes('LIMITE ULTRAPASSADO')) caso = 'limite';
return [{ json: { caso, numero: r ? r.chamado_id : c.numero, row_number: r ? r.row_number : null, nome: r ? String(r.nome || '') : '', email: r ? String(r.email || '').trim() : '',
  whatsapp: r ? String(r.whatsapp || '') : '', texto: c.texto } }];

const r = $('Reply: achar chamado').first().json, c = $('Classificar').first().json;
let ia = ''; try { ia = (($json.content || []).filter(x => x.type === 'text').map(x => x.text).join('
') || '').trim(); } catch (e) {}
const corpo = (ia || String(r.texto).trim()).slice(0, 3600);
const texto = 'PRÉVIA - chamado ' + r.numero + '
Para: ' + r.email + (ia ? '' : '
(A IA não respondeu. Este é o seu texto, sem revisão.)') + '

' + corpo
  + '

---
Toque em Enviar para mandar ao cliente. Para mudar, responda de novo a mensagem do chamado.';
return [{ json: { texto, linha: { row_number: r.row_number, previa: 'previa_' + c.msg_id + c.chat } } }];

const c = $('Classificar').first().json;
const r = $('Enviar: ler chamados').all().map(i => i.json).filter(x => x && x.row_number && String(x.chamado_id).trim() === c.numero).pop() || {};
const p = String(r.previa || '').trim();
let caso = 'antiga';
if (p === c.enviada) caso = 'ja_enviada'; else if (p === c.previa && String(r.email || '').includes('@')) caso = 'enviar'; else if (p === c.previa) caso = 'sem_email';
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/\n/g, '<br>');
return [{ json: { caso, numero: r.chamado_id || c.numero, nome: String(r.nome || ''), email: String(r.email || '').trim(), html_texto: esc(c.texto),
  linha: { row_number: r.row_number, status: 'respondido', resposta: c.texto.replace(/^[=+@-]+/, ''), data_resposta: new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' }).replace(',', '').slice(0, 16), previa: c.enviada } } }];

// Netliss - Pix de comissao feito (rota no cenario do reply do Telegram)
// Entrada: o update do Telegram (botao "Pix feito" ou reply "ok" na mensagem do lote) + a aba Lotes.
// Saida: o que fazer (pagar | ja_pago | nao_achou), o e-mail-recibo e a linha atualizada do lote.
const NL = String.fromCharCode(10);
function txt(v) { return String(v == null ? '' : v).trim(); }
function lerJson(v) { if (v && typeof v === 'object') { return v; } try { return JSON.parse(String(v || 'null')); } catch (e) { return null; } }
function num(v) { const s = txt(v).replace('R$', '').trim(); if (!s) { return 0; } const t = s.indexOf(',') > -1 ? s.split('.').join('').replace(',', '.') : s; const n = Number(t); return isNaN(n) ? 0 : n; }
function reais(n) { return 'R$ ' + (Math.round(n * 100) / 100).toFixed(2).replace('.', ','); }
function esc(s) { return txt(s).split('&').join('&amp;').split('<').join('&lt;').split('>').join('&gt;'); }
function p2(n) { n = Number(n || 0); return n < 10 ? '0' + n : String(n); }
function partesSP(ms) { const p = {}; for (const x of new Intl.DateTimeFormat('en-GB', { timeZone: 'America/Sao_Paulo', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date(ms))) { p[x.type] = x.value; } return p; }

const U = $('Telegram').first().json;
const cbId = txt((U.callback_query || {}).id);
const cbData = txt((U.callback_query || {}).data);
const textoMsg = txt(((U.message || {}).reply_to_message || {}).text);
let lote = '';
if (cbData.indexOf('afpago_') === 0) { lote = cbData.slice(7); }
else { const i = textoMsg.indexOf('Lote: '); if (i > -1) { lote = textoMsg.slice(i + 6).split(NL)[0].trim(); } }
lote = lote.replace(/[^A-Z0-9-]/g, '');

const objs = $('Afiliado: ler Lotes').all().map(i => i.json).filter(x => x && x.row_number);
const chaves = objs.length ? Object.keys(objs[0]).filter(k => k !== 'row_number') : [];
const rows = objs.map(o => chaves.map(k => o[k] == null ? '' : String(o[k])));
// Lotes: 0 lote 1 ref 2 email 3 titular 4 pix 5 whatsapp 6 referencia 7 vendas 8 valor 9 status 10 gerado_em 11 pago_em
let pos = -1;
for (let i = 0; i < rows.length; i++) { if (txt(rows[i][0]) === lote && lote) { pos = i; break; } }
const out = { acao: 'nao_achou', lote: lote, linha_range: '', linha_corpo: '', email: null, aviso: '' };

let botao = '';
async function responderBotao(t) { botao = t; }

if (pos < 0) {
  out.aviso = '⚠️ Não encontrei o lote ' + (lote || '(sem número)') + ' na planilha. Nenhum recibo foi enviado.';
  await responderBotao('Lote não encontrado');
} else {
  const l = rows[pos].slice(0, 12); while (l.length < 12) { l.push(''); }
  if (txt(l[9]) === 'paga') {
    out.acao = 'ja_pago';
    out.aviso = 'ℹ️ O lote ' + lote + ' já estava marcado como pago em ' + txt(l[11]) + '. Nenhum recibo novo foi enviado.';
    await responderBotao('Este lote já estava pago');
  } else {
    const h = partesSP(Date.now());
    const hoje = h.day + '/' + h.month + '/' + h.year;
    l[9] = 'paga'; l[11] = hoje + ' ' + h.hour + ':' + h.minute;
    out.acao = 'pagar';
    out.linha = { row_number: objs[pos].row_number }; if (chaves[9]) out.linha[chaves[9]] = l[9]; if (chaves[11]) out.linha[chaves[11]] = l[11];
    const valor = reais(num(l[8]));
    const qtd = Number(l[7] || 0);
    const primeiro = esc(txt(l[3]).split(' ')[0]);
    out.email = {
      para: txt(l[2]),
      assunto: 'Recibo Netliss: comissão de ' + valor + ' paga via Pix',
      html: "<div style='font-family:Arial,Helvetica,sans-serif;max-width:600px;margin:0 auto;background:#ffffff;border-radius:14px;overflow:hidden;border:1px solid #111'>" +
        "<div style='background:#0A0A0A;padding:16px 20px;text-align:center'><img src='https://i.imgur.com/9WE3IIp.png' alt='Netliss.com' width='190' style='max-width:190px;width:55%;height:auto;display:block;margin:0 auto'></div>" +
        "<div style='background:#C3F53C;height:4px'></div><div style='padding:28px 24px;color:#1a1a1a;line-height:1.62'>" +
        "<div style='color:#6b7a55;font-size:11px;letter-spacing:2px;text-transform:uppercase;margin-bottom:8px'>Recibo de comissão</div>" +
        "<h2 style='margin:0 0 14px;font-size:21px;color:#0A0A0A'>Olá, " + primeiro + "! Sua comissão foi paga.</h2>" +
        "<p style='margin:0 0 16px'>A Netliss confirma o pagamento da sua comissão de afiliado via Pix:</p>" +
        "<div style='background:#0A0A0A;border:1px solid #C3F53C;border-radius:10px;padding:18px;margin:0 0 20px;color:#ffffff;font-size:15px;line-height:1.9'>" +
        "<b style='color:#C3F53C'>Valor depositado:</b> " + valor + "<br>" +
        "<b style='color:#C3F53C'>Data do pagamento:</b> " + hoje + "<br>" +
        "<b style='color:#C3F53C'>Referente às vendas de:</b> " + esc(l[6]) + " (" + p2(qtd) + (qtd === 1 ? " venda" : " vendas") + ")<br>" +
        "<b style='color:#C3F53C'>Chave Pix:</b> " + esc(l[4]) + "<br>" +
        "<b style='color:#C3F53C'>Titular:</b> " + esc(l[3]) + "<br>" +
        "<b style='color:#C3F53C'>Lote:</b> " + esc(lote) + "</div>" +
        "<p style='margin:0 0 8px;color:#333'>Obrigado por divulgar a Netliss! Para ver seus resultados, entre no chat do site em <b>Ganhe dinheiro indicando a Netliss</b> e depois em <b>Já sou afiliado</b>.</p>" +
        "</div></div><div style='max-width:600px;margin:10px auto 0;text-align:center;color:#888;font-size:11px;font-family:Arial,sans-serif'>netliss.com &middot; Programa de Afiliados Netliss</div>"
    };
    out.aviso = '✅ PIX REGISTRADO' + NL + 'Lote ' + lote + ' — ' + valor + ' para ' + txt(l[3]) + NL + 'Recibo enviado para ' + txt(l[2]) + '.';
    await responderBotao('Registrando o pagamento...');
  }
}
out.tem_email = out.email ? 'sim' : 'nao';
out.cb_id = cbId; out.botao = botao;
out.reply_to = String(((U.callback_query || {}).message || {}).message_id || ((U.message || {}).reply_to_message || {}).message_id || '');
return [{ json: out }];
